// A lead as your website form or CRM would send it. "Test workflow" runs the whole flow on it.
return [{ json: { source: 'sample', body: { name: 'Dana Ortiz', email: 'dana@brightsmiledental.com', company: 'Bright Smile Dental',
  website: 'brightsmiledental.com', phone: '+1 555 010 2233',
  message: 'We run three dental offices (about 30 staff) and spend hours a week chasing insurance claims and re-entering patient data. We want this sorted before January. Can we talk next week?' } } }];

// Reads your form or payload with the field_* names in Config (dotted paths allowed), falling back to common names.
const cfg = $('Config').first().json;
const get = (o, p) => String(p || '').split('.').reduce((v, k) => v == null ? v : v[k], o);
const FREE = ['gmail.com','googlemail.com','yahoo.com','hotmail.com','outlook.com','live.com','msn.com','icloud.com','me.com','aol.com','proton.me','protonmail.com','gmx.com','mail.com','yandex.com','zoho.com'];
const DISPOSABLE = ['mailinator.com','guerrillamail.com','10minutemail.com','tempmail.com','temp-mail.org','trashmail.com','yopmail.com','sharklasers.com'];
const SPAMMY = /\b(seo services|backlinks?|guest post|link building|crypto|casino|forex|loan offer|web design services|rank (you|your site) #?1)\b/i;
const b = $json.body || $json;
const pick = (key, ...alts) => { for (const k of [cfg[key], ...alts]) { const v = get(b, k); if (v != null && String(v).trim()) return String(v).trim(); } return ''; };
const name = pick('field_name', 'Name', 'full_name', 'firstname');
const email = pick('field_email', 'Work email', 'Email', 'email_address').toLowerCase();
const message = pick('field_message', 'How can we help?', 'Message', 'comments', 'notes');
let website = pick('field_website', 'Website', 'url', 'domain').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const emailDomain = (email.split('@')[1] || '');
const free = FREE.includes(emailDomain);
const domain = website || (free ? '' : emailDomain);
const urls = (message.match(/https?:\/\//g) || []).length;
const spam = [DISPOSABLE.includes(emailDomain) && 'disposable email', SPAMMY.test(message) && 'sales pitch wording', urls > 2 && 'many links'].filter(Boolean);
const problem = [!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email) && 'no valid email', !message && !name && 'empty submission'].filter(Boolean).join(', ');
const [first, ...rest] = name.split(/\s+/);
return { json: { ref: email || name || '(no email)', name, first_name: first || '', last_name: rest.join(' '), email, company: pick('field_company', 'Company', 'company_name'),
  domain, free_email: free, phone: pick('field_phone', 'Phone', 'phone_number'), message: message.slice(0, 4000),
  source: $json.source || ($json.formMode ? 'n8n form' : 'website form'), spam_signals: spam, problem } };

// The same person submitting twice (double click, re-sent webhook) within dedupe_hours is handled once.
// Kept in the workflow's static data, which n8n saves on production runs only.
const cfg = $('Config').first().json, sd = $getWorkflowStaticData('global'), now = Date.now();
const seen = sd.seen || {}, win = Number(cfg.dedupe_hours || 24) * 36e5, out = [];
for (const k of Object.keys(seen)) if (now - seen[k] > win) delete seen[k];
$input.all().forEach((i, n) => { const k = i.json.email; if (k && seen[k]) return; if (k) seen[k] = now; out.push({ json: i.json, pairedItem: n }); });
sd.seen = seen;
return out;

// Adds what HubSpot already knows. Customers skip qualification and go straight to their owner.
const lead = $('Normalize lead').item.json, c = ($json.results || [])[0];
const p = c ? c.properties : {};
return { json: Object.assign({}, lead, { contact_id: c ? c.id : '', lifecycle: p.lifecyclestage || '', current_owner_id: p.hubspot_owner_id || '',
  existing_customer: ['customer', 'evangelist'].includes(p.lifecyclestage || '') }) };

