// The AI scores; your rules decide. Tier comes from the score and your thresholds, not from the model's own label.
const cfg = $('Config').first().json, lead = $('Merge CRM record').item.json, ai = $json.output || {};
const score = Math.max(0, Math.min(100, Math.round(Number(ai.score) || 0)));
let tier = score >= Number(cfg.hot_threshold) ? 'hot' : score >= Number(cfg.warm_threshold) ? 'warm' : 'nurture';
if (ai.tier === 'spam' || (lead.spam_signals.length && score < 30)) tier = 'spam';
if (tier === 'hot' && lead.free_email && score < 90) tier = 'warm';          // a personal address needs very strong intent to skip the queue
let owners = {}; try { owners = JSON.parse(cfg.owners_json || '{}'); } catch (e) {}
const owner = owners[ai.segment] || owners.default || {};
const local = $now.setZone(cfg.timezone);
const after_hours = local.weekday > 5 || local.hour < Number(cfg.business_start_hour) || local.hour >= Number(cfg.business_end_hour);
const status = { hot: cfg.lead_status_hot, warm: cfg.lead_status_warm, nurture: cfg.lead_status_nurture }[tier] || '';
return { json: Object.assign({}, lead, { score, tier, segment: ai.segment || 'unknown', industry: ai.industry || '', summary: ai.company_summary || '',
  reasons: (ai.fit_reasons || []).slice(0, 3), red_flags: ai.red_flags || [], next_step: ai.next_step || '', lead_status: status,
  owner_name: owner.name || '', owner_email: owner.email || '', owner_id: owner.hubspot_owner_id || lead.current_owner_id || '', after_hours,
  reply_subject: ai.reply_subject || 'Thanks for getting in touch', reply_body: ai.reply_body || '' }) };

// Free slots in business hours over the next 5 working days, at least 2 hours out, one per day.
const cfg = $('Config').first().json, tz = cfg.timezone, mins = Number(cfg.meeting_minutes || 30);
const busy = ((($json.calendars || {})[cfg.calendar_id] || {}).busy || []).map(b => [DateTime.fromISO(b.start).toMillis(), DateTime.fromISO(b.end).toMillis()]);
const free = (s, e) => !busy.some(([bs, be]) => s < be && e > bs);
const earliest = $now.setZone(tz).plus({ hours: 2 }).toMillis(), out = [];
let day = $now.setZone(tz).startOf('day'), days = 0;
while (out.length < 3 && days < 5) {
  if (day.weekday <= 5) {
    days++;
    for (let t = day.set({ hour: Number(cfg.business_start_hour) }); t.plus({ minutes: mins }) <= day.set({ hour: Number(cfg.business_end_hour) }); t = t.plus({ minutes: 30 })) {
      const s = t.toMillis(), e = t.plus({ minutes: mins }).toMillis();
      if (s >= earliest && free(s, e)) { out.push({ start: t.toISO(), end: t.plus({ minutes: mins }).toISO(), label: t.toFormat("ccc d LLL, h:mm a ZZZZ") }); break; }
    }
  }
  day = day.plus({ days: 1 });
}
return { json: { slots: out, has_slot: out.length > 0 } };

